package main

// tr devuelve la traducción de una cadena de interfaz. El español es la fuente
// original y el idioma predeterminado; las cadenas técnicas se conservan.
func tr(lang, source string) string {
	if lang == "" || lang == "es" {
		return source
	}
	if translated, ok := translations[lang][source]; ok {
		return translated
	}
	if translated, ok := extraTranslations[lang][source]; ok {
		return translated
	}
	if translated, ok := appearanceTranslations[lang][source]; ok {
		return translated
	}
	if translated, ok := eggsConfigTranslations[lang][source]; ok {
		return translated
	}
	return source
}

func validLanguage(lang string) bool {
	switch lang {
	case "es", "en", "pt", "it":
		return true
	}
	return false
}

